// Simulation stand-ins for the Xilinx primitives used by gb_clocks.sv.
// The clocks are generated by the bench (sim/tb/sim_main.cpp, or a unit
// bench with timing) as inputs of the bench's top module, with clk_sys
// rising together with every third clk_mem rising edge, exactly as the MMCM
// outputs are aligned.
// SPDX-License-Identifier: GPL-2.0-or-later

// (TB_TOP: the bench module that has the clocks, tb_top unless defined.)
`ifndef TB_TOP
`define TB_TOP tb_top
`endif

module MMCME2_BASE #(
	parameter BANDWIDTH = "OPTIMIZED",
	parameter real CLKIN1_PERIOD = 20.0,
	parameter integer DIVCLK_DIVIDE = 1,
	parameter real CLKFBOUT_MULT_F = 5.0,
	parameter real CLKFBOUT_PHASE = 0.0,
	parameter real CLKOUT0_DIVIDE_F = 1.0,
	parameter integer CLKOUT1_DIVIDE = 1,
	parameter integer CLKOUT2_DIVIDE = 1,
	parameter integer CLKOUT3_DIVIDE = 1,
	parameter integer CLKOUT4_DIVIDE = 1,
	parameter integer CLKOUT5_DIVIDE = 1,
	parameter real CLKOUT0_PHASE = 0.0,
	parameter real CLKOUT1_PHASE = 0.0,
	parameter real CLKOUT2_PHASE = 0.0,
	parameter real CLKOUT3_PHASE = 0.0,
	parameter real CLKOUT4_PHASE = 0.0,
	parameter real CLKOUT5_PHASE = 0.0,
	parameter real CLKOUT0_DUTY_CYCLE = 0.5,
	parameter real CLKOUT1_DUTY_CYCLE = 0.5,
	parameter real CLKOUT2_DUTY_CYCLE = 0.5,
	parameter real CLKOUT3_DUTY_CYCLE = 0.5,
	parameter real CLKOUT4_DUTY_CYCLE = 0.5,
	parameter real CLKOUT5_DUTY_CYCLE = 0.5,
	parameter STARTUP_WAIT = "FALSE"
) (
	output CLKOUT0, output CLKOUT0B, output CLKOUT1, output CLKOUT1B,
	output CLKOUT2, output CLKOUT2B, output CLKOUT3, output CLKOUT3B,
	output CLKOUT4, output CLKOUT5, output CLKOUT6,
	output CLKFBOUT, output CLKFBOUTB, input CLKFBIN,
	output LOCKED, input CLKIN1, input PWRDWN, input RST
);
	// the bench checks the configuration it models (gb_clocks.sv)
	initial begin
		if (DIVCLK_DIVIDE != 2 || CLKFBOUT_MULT_F != 38.375 || CLKOUT0_DIVIDE_F != 10.0 ||
		    CLKOUT1_DIVIDE != 30 || CLKOUT2_DIVIDE != 5 || CLKOUT4_DIVIDE != 10 || CLKOUT5_DIVIDE != 20)
			$fatal(1, "MMCME2_BASE model: unexpected configuration");
	end
	assign CLKOUT0 = `TB_TOP.clk_mem;
	assign CLKOUT1 = `TB_TOP.clk_sys;
	assign CLKOUT2 = `TB_TOP.clk_mem;
	assign CLKOUT3 = `TB_TOP.clk_sys;
	assign CLKOUT4 = `TB_TOP.clk_mem;   // (its phase delay is timed by Vivado, not simulated)
`ifdef FALCON_CPU060
	assign CLKOUT5 = `TB_TOP.clk_cpu;   // the 68060 variant's processor clock
`else
	assign CLKOUT5 = 1'b0;
`endif
	assign {CLKOUT0B, CLKOUT1B, CLKOUT2B, CLKOUT3B, CLKOUT6, CLKFBOUTB} = '0;
	assign CLKFBOUT = CLKIN1;
	assign LOCKED = `TB_TOP.mmcm_locked;
endmodule

module BUFG (input I, output O);
	assign O = I;
endmodule

// output DDR register: D1 after the rising edge of C, D2 after the falling
// edge. OPPOSITE_EDGE (gb_sdram_ctrl forwards the SDRAM clock with D1 = 0,
// D2 = 1, constants): the clock itself selects. SAME_EDGE (gb_fb's SRAM
// write enable): both inputs are taken at the rising edge, D1 is out from
// it and D2 from the falling edge after it, as a register that changes at
// both edges (so that a model sampling the pin at an edge sees the half
// period that ends there).
module ODDR #(
	parameter DDR_CLK_EDGE = "OPPOSITE_EDGE",
	parameter INIT = 1'b0,
	parameter SRTYPE = "SYNC"
) (
	output Q, input C, input CE, input D1, input D2, input R, input S
);
	generate
		if (DDR_CLK_EDGE == "SAME_EDGE") begin : same
			reg q = INIT, d2 = INIT;
			always @(posedge C or negedge C) begin
				if (C) begin
					q  <= D1;
					d2 <= D2;
				end
				else q <= d2;
			end
			assign Q = q;
		end
		else begin : opp
			assign Q = C ? D1 : D2;
		end
	endgenerate
endmodule
